import { readdirSync, readFileSync } from "fs";
import path from "path";
import { uniq } from "es-toolkit";
import { z } from "zod";
import LibsConfig from "../libs.json";

// `libs.json` is generated by `gulp libs` from the `libs/group-*` folders. It
// must mirror them: a group folder that is missing here is never built, and a
// selector list that drifted makes the compiler pick the wrong bundle.

const libsDir = path.resolve(__dirname, "../../libs");
const selectorsSchema = z.array(z.string());

function selectorsOf(folder: string): string[] {
  return selectorsSchema.parse(
    JSON.parse(
      readFileSync(path.join(libsDir, folder, "selectors.json"), "utf8")
    )
  );
}

const groupFolders = readdirSync(libsDir).filter((name) =>
  name.startsWith("group-")
);

const bundles = [
  {
    bundle: "free",
    entries: LibsConfig.free,
    suffix: "",
    folders: groupFolders.filter((name) => !name.endsWith("-pro"))
  },
  {
    bundle: "pro",
    entries: LibsConfig.pro,
    suffix: "-pro",
    folders: groupFolders.filter((name) => name.endsWith("-pro"))
  }
];

describe.each(bundles)(
  "the $bundle lib groups",
  ({ entries, suffix, folders }) => {
    const folderOf = (name: string): string => `${name}${suffix}`;

    it("lists every group folder once", () => {
      expect(entries.map(({ name }) => folderOf(name)).sort()).toEqual(
        [...folders].sort()
      );
    });

    it("points every group at its folder", () => {
      expect(entries.map(({ path: entryPath }) => entryPath)).toEqual(
        entries.map(({ name }) => `./editor/js/libs/${folderOf(name)}`)
      );
    });

    it("carries the selectors of every group folder", () => {
      expect(entries.map(({ selectors }) => selectors)).toEqual(
        entries.map(({ name }) => selectorsOf(folderOf(name)))
      );
    });

    it("gives every pair the selectors of its two base groups", () => {
      const pairs = entries.filter(({ name }) => /^group-\d+_\d+$/.test(name));

      expect(pairs.length).toBeGreaterThan(0);
      expect(pairs.map(({ selectors }) => selectors)).toEqual(
        pairs.map(({ name }) => {
          const [first, second] = name.replace("group-", "").split("_");

          return uniq([
            ...selectorsOf(folderOf(`group-${first}`)),
            ...selectorsOf(folderOf(`group-${second}`))
          ]);
        })
      );
    });

    it("gives the all-in-one group the selectors of every base group", () => {
      const bases = entries.filter(({ name }) => /^group-\d+$/.test(name));
      const all = entries.find(({ name }) => name === "group-all");

      expect(all?.selectors).toEqual(
        uniq(bases.flatMap(({ name }) => selectorsOf(folderOf(name))))
      );
    });
  }
);
